return new{playing=UnityEditor.EditorApplication.isPlaying,scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path,dirty=UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty,parts=UnityEngine.Object.FindObjectsByType<UnityEngine.SkinnedMeshRenderer>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).Where(r=>r.name.StartsWith("Bandit_")).GroupBy(r=>r.transform.root).Select(g=>new{root=g.Key.name,count=g.Count(),meshes=g.Select(r=>new{r.name,mesh=UnityEditor.AssetDatabase.GetAssetPath(r.sharedMesh),prefab=UnityEditor.PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(r.gameObject),mats=r.sharedMaterials.Select(m=>m==null?"null":m.name+":"+m.shader.name).ToArray()}).ToArray()}).ToArray()};
